// =============================================================================
//  LocalizationHR.cpp  -- The Hell 4 -- Croatian overlay  (th4)
//  LANG_HR = 21. Latin script, REAL CP1250 DIACRITICS (the Czech/Polish model).
//
//  Written by the loc toolkit (2026-10-06) from UTF-8 translation data that is NOT part
//  of the source tree. From now on this file IS the source: edit it by hand like any other
//  Localization<XX>.cpp, following the encoding rules below. Translated by machine (Claude) with
//  the Czech and Polish locs as grammatical references; no native review yet -- fixes from
//  Croatian (and Serbian/Bosnian) players are expected.
//
//  ---- ENCODING ------------------------------------------------------------
//  * Byte encoding is CP1250. Read/write this file in Python with 'latin-1' for raw bytes.
//  * Croatian letters are \xNN escapes so the file stays ASCII:
//      C-caron \xC8  C-acute \xC6  D-stroke \xD0  S-caron \x9A*  Z-caron \x8E
//      lowercase: \xE8 \xE6 \xF0 \x9A \x9E
//      * S-caron is the lowercase byte \x9A in every table but HR_Menu: the capital \x8A sits inside the
//        colour-control window 0x80..0x8B (Tooltip.cpp IsColorControlByte). The caps-only fonts draw both the same.
//  * *** THE GREEDY-HEX C2022 TRAP APPLIES ***: a \x escape eats every following ASCII hex digit
//    INCLUDING a-f / A-F: write "\xE8""e", never the escape glued to a hex letter.
//    Check with regex  \\x[0-9A-Fa-f]{2}[0-9A-Fa-f]  -> must be 0 hits.
//  * The in-game CEL fonts are CAPS-ONLY; lowercase bytes alias the uppercase glyph.
//  * HR_Menu is drawn ONLY by the META-MENU atlas (ui_art font16/24/30/42, raw bytes, no colour codes).
//    TH4loc_hrv.mor ships that atlas with the Croatian cells, so HR_Menu has full diacritics. The trait
//    texts are drawn by BOTH fonts (character creation + the in-game perk tooltip), so they follow the
//    in-game rule. Keys must byte-exactly match the English source literal.
//
//  ---- FONTS ---------------------------------------------------------------
//  TH4loc_hrv.mor (mounted at 8900 only when language == HR) = the Czech pack's fonts + C-acute and
//  D-stroke. Tables: Codepage_Croatian / FontIndex*_Croatian / FontWidth{Mid,Big}_Croatian in
//  dataseg.cpp; FontWidthSmall[109..110] appended. The pack and those tables are a matched pair.
//
//  ---- GRAMMAR CONVENTIONS (keep consistent) --------------------------------
//  * Plural triples follow the Russian rule: _one = 1, 21, 31... (not 11); _few = 2-4, 22-24... (not
//    12-14); _many = the rest. Code: the charges line and formatGoldAmount() in Panel.cpp.
//  * Griswold's possessive is always the GENITIVE "Griswolda" (never "Griswoldov"), so the Dark Campaign
//    rename (Localization.cpp DarkCampaignRenameSmith) can swap it for "Hephasta".
//  * "Relict of X" = "Relikvija X" exactly; classic mode swaps that prefix for "Svitak " (Item.cpp).
//
//  English source is inviolable -- translate via these overlays only.
// =============================================================================
#include "stdafx.h"

struct UiStr  { const char* en; const char* tr; }; // .tr column holds the Croatian text
struct IdxStr { int index; const char* tr; };

// MUST stay in sync with the master enum in Localization.cpp -- the ids are array
// indices shared across translation units.
enum {
	OVL_UI = 0, OVL_MENU, OVL_UNIQUE_ITEM, OVL_AFFIX_PREFIX, OVL_AFFIX_SUFFIX,
	OVL_BASE_ITEM, OVL_BASE_NAME2, OVL_ELEMENT, OVL_SPICIES, OVL_ICEAGE,
	OVL_SPELL, OVL_SPELL_NOM, OVL_PERK_NAME, OVL_PERK_DESC, OVL_WARP,
	OVL_WARP_OBL,
	OVL_STR_COUNT
};
enum { OVL_SPEECH = 0, OVL_ONSCREEN, OVL_QUEST, OVL_IDX_COUNT };

// A lone placeholder row ({ 0, 0 } / { -1, 0 }) counts as 0 rows => English fallback.
static bool isPlaceholder( const UiStr&  r ) { return r.en == 0; }
static bool isPlaceholder( const IdxStr& r ) { return r.index < 0 && r.tr == 0; }

template<typename T, size_t N>
static int countRows( const T (&arr)[N] )
{
	if( N == 1 && isPlaceholder( arr[0] ) ) return 0;
	return (int)N;
}

