const UiStr* HR_GetStrTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_UI:           *n = countRows( HR_Ui ); return HR_Ui;
		case OVL_MENU:         *n = countRows( HR_Menu ); return HR_Menu;
		case OVL_UNIQUE_ITEM:  *n = countRows( HR_UniqueItem ); return HR_UniqueItem;
		case OVL_AFFIX_PREFIX: *n = countRows( HR_AffixPrefix ); return HR_AffixPrefix;
		case OVL_AFFIX_SUFFIX: *n = countRows( HR_AffixSuffix ); return HR_AffixSuffix;
		case OVL_BASE_ITEM:    *n = countRows( HR_BaseItem ); return HR_BaseItem;
		case OVL_BASE_NAME2:   *n = countRows( HR_BaseName2 ); return HR_BaseName2;
		case OVL_ELEMENT:      *n = countRows( HR_Element ); return HR_Element;
		case OVL_SPICIES:      *n = countRows( HR_Spicies ); return HR_Spicies;
		case OVL_ICEAGE:       *n = countRows( HR_IceAge ); return HR_IceAge;
		case OVL_SPELL:        *n = countRows( HR_Spell ); return HR_Spell;
		case OVL_SPELL_NOM:    *n = countRows( HR_SpellNom ); return HR_SpellNom;
		case OVL_PERK_NAME:    *n = countRows( HR_PerkName ); return HR_PerkName;
		case OVL_PERK_DESC:    *n = countRows( HR_PerkDesc ); return HR_PerkDesc;
		case OVL_WARP:         *n = countRows( HR_Warp ); return HR_Warp;
		case OVL_WARP_OBL:     *n = countRows( HR_WarpOblique ); return HR_WarpOblique;
	}
	*n = 0; return 0;
}

const IdxStr* HR_GetIdxTable( int ovlId, int* n )
{
	switch( ovlId ){
		case OVL_SPEECH:   *n = countRows( HR_Speech ); return HR_Speech;
		case OVL_ONSCREEN: *n = countRows( HR_OnScreen ); return HR_OnScreen;
		case OVL_QUEST:    *n = countRows( HR_Quest ); return HR_Quest;
	}
	*n = 0; return 0;
}

