// HR_GCInfoDesc
const char* HR_GCInfoDesc( int gc )
{
	switch( gc ){
		case 0: return "Ni\x9Ata (presko\xE8""eno)";
		case 1: return "Automatsko spremanje\n\n\nMijenja stil igre\n\nIgra\xE8 ne mora ru\xE8no spremati igru, spremanje se obavlja automatski, ba\x9A kao u igri za vi\x9A""e igra\xE8""a.";
		case 2: return "Vezana oprema\n\n\nDodaje izazov\n\nOnemogu\xE6uje opremanje i skidanje predmeta u borbi (osim onih u rukama).";
		case 3: return "Ispadanje predmeta\n\n\nDodaje izazov\n\nKad umre\x9A, ispu\x9Ata\x9A opremljene predmete.\n\nUpozorenje: ako ispu\x9Atene predmete ne pokupi\x9A u istoj sesiji igre, nestat \xE6""e.";
		case 4: return "Bez napora\n\n\nOlak\x9A""ava igru\n\n\xC8udovi\x9Ata ti nanose samo pola \x9Atete.\nLak\x9A""e od toga ne mo\x9E""e.";
		case 5: return "Od zemlje\n\n\nDodaje izazov\n\nMje\x9Atani ti ne\xE6""e prodavati predmete.\n\nIpak, i dalje \xE6""e ti pru\x9E""ati svoje usluge: tra\xE8""eve, razgovore o zadacima, popravak, identifikaciju, za\xE8""aravanje, izradu, dodavanje utora, punjenje.";
		case 6: return "Nemogu\xE6""e\n\n\nOte\x9E""ava igru\n\n\xC8udovi\x9Ata ti nanose dvostruku \x9Atetu.\nTe\x9E""e od toga ne mo\x9E""e.";
		case 7: return "Prohibicija\n\n\nDodaje izazov\n\n\xC8udovi\x9Ata vi\x9A""e ne\xE6""e nasumi\xE8no ispu\x9Atati eliksire atributa\nNapomena: sposobnost Te\x9Aki pijanac i dalje daje eliksire od jedinstvenih \xE8udovi\x9Ata";
		case 8: return "Puni kontakt\n\n\nOlak\x9A""ava igru\n\n\xC8udovi\x9Ata s napadima na daljinu ne uzmi\xE8u.";
		case 9: return "No\xE6ni rod\n\n\nPretvara te u vampira\n\nKrv ti je i \x9Eivot i smrt. Tvoja glad je nezasitna, ali ima\x9A sve \x9Ato ti treba za lov na slabe\n\nOvo mijenja na\xE8in igranja.\nNe koristi\x9A predmete i oslanja\x9A se na uro\xF0""ene mo\xE6i.";
		case 10: return "Sijeci i kolji\n\n\nOlak\x9A""ava igru\n\nVi\x9A""e ne mora\x9A mijenjati vrstu oru\x9Eja (o\x9Atro ili tupo) prema vrsti \xE8udovi\x9Ata. Sva oru\x9Eja nanose standardnu \x9Atetu svim vrstama \xE8udovi\x9Ata.";
		case 11: return "Cijepljen\n\n\nOlak\x9A""ava igru\n\n\xC8udovi\x9Ata gube sve imunitete i ne treba\x9A mijenjati \xE8""arolije - djeluje svaka vrsta \xE8""arolije.\nNe odnosi se na Kamenu kletvu, Ko\x9Atani duh te elementarne i svete \xE8""arolije.";
		case 12: return "To je moja tajna\n\n\nOlak\x9A""ava igru\n\nBijes nema vrijeme obnove i mo\x9E""e se ponovno baciti \xE8im zavr\x9Ai.";
		case 13: return "Bez regeneracije\n\n\nDodaje izazov\n\nLik nema osnovnu regeneraciju \x9Eivota i mane.";
		case 14: return "\xC8iste ruke\n\n\nDodaje izazov\n\n\xC8udovi\x9Ata ne ispu\x9Ataju predmete koje lik mo\x9E""e opremiti.\nIgra\xE8 ih mora nabaviti kupnjom i/ili za\xE8""aravanjem.";
		case 15: return "Ledeno doba\n\n\nKozmeti\xE8ka promjena\n\nRazine tamnice izgledaju kao usred duboke, duboke zime, sve je okovano ledom i smrznuto.\nMo\x9E""e\x9A li zamisliti kako bi izgledao zale\xF0""eni Pakao?";
		case 16: return "Beskrajni dan\n\n\nMijenja stil igre\n\nSvaki put stvara se ista tamnica s istim \xE8udovi\x9Atima. Mo\x9E""e\x9A igrati i svaki put popravljati svoje vrijeme.";
		case 17: return "Ja\xE8""a \xE8udovi\x9Ata\n\n\nOte\x9E""ava igru\n\n\xC8udovi\x9Ata imaju +200% \x9Eivota.";
		case 18: return "Neuni\x9Ativi predmeti\n\n\nOlak\x9A""ava igru\n\nPredmeti se ne\xE6""e uni\x9Atiti kad izdr\x9Eljivost padne na nulu. Umjesto toga postat \xE6""e neupotrebljivi dok se ne poprave.";
		case 19: return "Bez karte\n\n\nDodaje izazov\n\nAutomatska karta nije dostupna\nPut kroz tamnice morat \xE6""e\x9A na\xE6i bez nje\n\nVe\xE6 se osje\xE6""a\x9A izgubljeno?";
		case 20: return "Dvostruka \x9Ateta\n\n\nOlak\x9A""ava igru\n\nTvoji napadi nanose \xE8udovi\x9Atima dvostruku \x9Atetu\n\nUpozorenje: igra bi mogla postati razo\xE8""aravaju\xE6""e laka.\nNe biraj ovo ako \x9E""eli\x9A zadr\x9E""ati uzbu\xF0""enje borbe.";
		case 21: return "Ne vidim zlo\n\n\nDodaje izazov\n\nVi\xF0""enje ne isti\xE8""e \xE8udovi\x9Ata u tami.";
		case 22: return "Crna smrt\n\n\nNosi\x9A zarazu\n\nKuga Crne smrti obuzela te. Polako \xE6""e razvijati te\x9Ake simptome koji \xE6""e te na kraju neizbje\x9Eno ubiti.\n\nNe mo\x9E""e\x9A je izlije\xE8iti, ne mo\x9E""e\x9A je ubla\x9Eiti i ne mo\x9E""e\x9A je zaustaviti. S vremenom \xE6""e biti sve te\x9E""a. Od ove smrtonosne bolesti nema bijega.";
		case 23: return "Peh\n\n\nDodaje izazov\n\nSre\xE6""a prije ili kasnije ponestane. Tvoja nije ni po\xE8""ela.\n\nIgru po\xE8inje\x9A sa svim atributima jednakima 5. Po novoj razini dobiva\x9A samo 2 boda atributa. Pronala\x9E""enje magi\xE8nih predmeta, ste\xE8""eno iskustvo i pronala\x9E""enje zlata smanjeni su za 75%. Igru po\xE8inje\x9A bez ikakvih predmeta.\n\nNema sposobnosti koje bi ti pomogle s iskustvom, ispadanjem eliksira, pronala\x9E""enjem magi\xE8nih predmeta i atributima po razini.";
		case 24: return "Nemilosrdno \x9E""eljezo\n\n\nDodaje izazov\n\nKlasi\xE8ni Ironman u Diablu bio je druga\xE8iji.\n\nNije bilo bonusa na atribute po razini, ni dodatnog iskustva, ni ulja ni identifikacije od bossova. Ni pobolj\x9A""anja MF-a.\n\nOvaj modifikator vra\xE6""a te tim korijenima.";
		case 25: return "Ubrzanje\n\n\nOlak\x9A""ava igru\n\nIskustvo je pove\xE6""ano 2x.";
		case 26: return "Askeza\n\n\nDodaje izazov\n\nIgra se sprema automatski.\n\nNakon smrti ispu\x9Ata\x9A predmete. Ne mo\x9E""e\x9A uskrsnuti u gradu (mora\x9A pokrenuti novu igru) i zato gubi\x9A sve ispu\x9Atene predmete.\n\nKao na\xE8in Hardcore, ali umjesto lika gubi\x9A opremljene predmete.";
		case 27: return "Terminator\n\n\nTi si jedinica serije Cyberdyne Systems. Model 101, infiltrator. Na\xE8in \xE8itanja-pisanja CPU-a aktiviran. Poslana u pro\x9Alost da izvr\x9Ai misiju.\n\nGlavna meta: Uber Diablo.\n\nSporedna meta: istrijebiti \xE8udovi\x9Ata.\n\nUvjet: doma\xE6im subjektima izgledati kao \xE8ovjek.\n\nOsnovne nadogradnje instalirane. Dodatne nadogradnje dostupne samou\xE8""enjem.";
		case 28: return "Supermutant\n\n\nTvoje tijelo mo\x9E""e nositi oru\x9Eje koje bi obi\xE8nog \xE8ovjeka prelomilo napola.\n\nMinigunovi.\n\nStvari koje ne bi smjele postojati na ovom svijetu. Vi\x9A""e ne baca\x9A \xE8""arolije. Ne treba\x9A ih.\n\nKad povu\xE8""e\x9A okida\xE8, rafal kida pakleni nakot kao papir u oluji.";
		case 29: return "Vojnik Enklave\n\n\nVojnik Oru\x9E""anih snaga Enklave, obu\xE8""en za istrebljivanje mutanata i genetske ne\xE8isto\xE6""e.\n\nNasukao se u svijetu koji nikad nije upoznao nuklearni oganj, ali u kojem vrvi gamad druge vrste - pakleni nakot.\n\nNeprijatelj se promijenio. Svrha nije.\n\nSposobnosti: rukuje energetskim oru\x9Ejem i postavlja borbene dronove. Vje\x9At u elementarnom ratovanju.";
		default: return nullptr;
	}
}

